package cn.iocoder.yudao.module.amazon.controller.admin.producttypedefinitions;
import cn.iocoder.yudao.framework.common.pojo.CommonResult; import cn.iocoder.yudao.module.amazon.controller.admin.products.vo.AmazonProductsReqVO; import cn.iocoder.yudao.module.amazon.service.producttypedefinitions.AmazonProductTypeDefinitionsService; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.annotation.Resource; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.Map;
/** Amazon Product Type Definitions 管理接口。 */
@Tag(name="管理后台 - Amazon Product Type Definitions") @RestController @RequestMapping("/amazon/product-type-definitions") public class AmazonProductTypeDefinitionsController { @Resource private AmazonProductTypeDefinitionsService service; @PostMapping("/search") @PreAuthorize("@ss.hasPermission('amazon:product-type-definitions:query')") public CommonResult<Map<String,Object>> search(@Valid @RequestBody AmazonProductsReqVO r){return CommonResult.success(service.search(r));} @PostMapping("/get") @PreAuthorize("@ss.hasPermission('amazon:product-type-definitions:query')") public CommonResult<Map<String,Object>> get(@Valid @RequestBody AmazonProductsReqVO r){return CommonResult.success(service.get(r));} }
